import click
import logging
from pathlib import Path

logging.basicConfig(level=logging.INFO)

def categorize_files(root_dir, dry_run=False):
    categories = {}
    for root, _, files in os.walk(root_dir):
        for file in files:
            _, ext = os.path.splitext(file)
            if ext not in categories:
                categories[ext] = []
            categories[ext].append(Path(root) / file)
    return categories

def move_files(categories, root_dir, dry_run=False):
    for ext, files in categories.items():
        if not ext:
            continue
        target_dir = Path(root_dir) / ext[1:]
        target_dir.mkdir(exist_ok=True)
        for file in files:
            try:
                if dry_run:
                    logging.info(f"Dry run: Moving {file} to {target_dir}")
                else:
                    shutil.move(file, target_dir)
                    logging.info(f"Moved {file} to {target_dir}")
            except Exception as e:
                logging.error(f"Error moving {file} to {target_dir}: {e}")

@click.command()
@click.option('--root', default='.', help='Root directory to scan')
@click.option('--dry-run', is_flag=True, help='Run without actually moving files')
def organize_files(root, dry_run):
    try:
        categories = categorize_files(root, dry_run)
        move_files(categories, root, dry_run)
    except Exception as e:
        logging.error(f"An error occurred: {e}")

