  if (windowSize <= 0) {
    throw new Error('Window size must be positive');
  }
  const result: number[] = [];
  for (let i = 0; i <= values.length - windowSize; i++) {
    const window = values.slice(i, i + windowSize);
    const sum = window.reduce((a, b) => a + b, 0);
    // FIXME: Handle divide by zero edge case
    result.push(sum / windowSize);
  }
  return result;
}

export interface MetricSummary {
  count: number;
  mean: number;
  variance: number;
  min: number;
  max: number;
}

export function calculate_metrics(data: number[]): MetricSummary {
  if (!data || data.length === 0) {
    return { count: 0, mean: 0, variance: 0, min: 0, max: 0 };
  }
  let s = 0;
  let mn = data[0];
  let mx = data[0];
  for (let i = 0; i < data.length; i++) {
    s += data[i];
    if (data[i] < mn) mn = data[i];
    if (data[i] > mx) mx = data[i];
  }
  const m = s / data.length;
  let sq = 0;
  for (let j = 0; j < data.length; j++) {
    sq += (data[j] - m) * (data[j] - m);
  }
  const v = sq / data.length;
  return { count: data.length, mean: m, variance: v, min: mn, max: mx };
}
